// 值是与其中汉字逐个对齐的拼音（空格分隔，标点不占位）。注音习惯同一到五年级：一 / 不 标变调，轻声词标轻声（葫芦 hú lu），
// 多音字按上下文（地 / 得 按用法），儿化的「儿」标 r，名词后缀单念的标 ér；单独一个字按它在课文里注的读音（六年级没有
// 识字表）。课本给字注的音照课本（磅礴的磅 páng、逶迤的迤 yí、坚劲的劲 jìng、风簸的簸 bǒ、弓缴的缴 zhuó、岐嶷的嶷 nì、
// 华罗庚的华 huà），注释说读什么就读什么（与 yú、孰为汝的为 wèi、知 zhì）；嘟囔句子里读轻声。六年级课文只给生字注音，
// 其余按普通话习惯。测试查：每课要用的中文都在表里、音节数等于汉字数；表里没有用不到的条目。
